    values := [String:String]{}

    loop line in text.trim().lines() {
        parts :: line.split("|").to_list()
        if parts.len() < 2 {
            eprint("error: malformed record: {line}")
            process.exit(1)
        }
        kind :: parts[0]
        key :: parts[1]
        if kind == "put" {
            if parts.len() < 3 {
                eprint("error: malformed put record: {line}")
                process.exit(1)
            }
            value :: parts[2]
            existing :: values.get(key)
            if existing == .None -> keys.push(~key)
            values[~key] = ~value
        } else if kind == "delete" {
            _ :: keys.remove(~key)
            _ :: values.pop(~key)
        } else {
            eprint("error: unknown record kind '{kind}' in line: {line}")
            process.exit(1)
        }
    }

    loop k in keys {
        v :: values.get(k) ?? ""
        print("{k}={v}")
    }
}
